import { CHARACTERS, TRAITS, EQUIPMENT, STRATEGIES, RECIPES, LEVEL_XP } from './data.js';
import { createGame, act, getSynergies, getTeamPower, getEnemy, getUnitStats, validateState, getCharacter, getEquipment } from './engine.js';

const paths = {
 star:'M12 2 15 9 22 12 15 15 12 22 9 15 2 12 9 9Z',
 swords:'m4 3 8 8-3 3-8-8V3h3Zm16 0-8 8 3 3 8-8V3h-3ZM4 20l5-5m6 0 5 5M2 16l6 6m8 0 6-6',
 grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',
 hammer:'m14 3 7 7-3 3-3-3-9 11-4-4L13 8l-3-3 4-2Z',
 help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 reset:'M3 10a9 9 0 1 1 2 8M3 3v7h7',
 coin:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0ZM12 7v10m3-7c0-3-6-3-6 0s6 1 6 4-6 3-6 0',
 heart:'M12 21 3 12a6 6 0 0 1 9-8 6 6 0 0 1 9 8Z',
 level:'m3 12 9-9 9 9-9 9-9-9Zm4 0 5-5 5 5-5 5-5-5Z',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm10-7a4 4 0 0 1 0 8m3 9v-2a4 4 0 0 0-3-4',
 plus:'M12 5v14M5 12h14',
 lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v11H4zM12 14v3',
 unlock:'M7 10V7a5 5 0 0 1 9-3M4 10h16v11H4zM12 14v3',
 refresh:'M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6m-4 9a9 9 0 0 0 15 2l3-3m0 6v-6h-6',
 arrow:'M4 12h16m-6-6 6 6-6 6',
 shop:'M3 9h18l-2-6H5L3 9Zm1 0v12h16V9M9 21v-8h6v8M3 9a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0',
 bag:'M4 7h16v15H4zM8 7V5a4 4 0 0 1 8 0v2',
 check:'m4 12 5 5L20 6',
 shield:'M12 2 3 6v7c0 5 9 9 9 9s9-4 9-9V6l-9-4Z',
 close:'m6 6 12 12M6 18 18 6',
 crown:'m2 6 5 5 5-8 5 8 5-5-3 13H5L2 6ZM5 22h14',
 route:'M5 5h12a4 4 0 0 1 0 8H7a4 4 0 0 0 0 8h12M5 2v6m14 10v6',
 info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 expand:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6',
 clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
};
const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = value => Number(value).toLocaleString('zh-CN');
const traitName = id => TRAITS.find(t=>t.id===id)?.name||id;
const rarity = ['','#bac7d7','#8dbb9f','#78a7d4','#b29aca','#d6b77e'];
const saveKey = 'currency-wars-classic-v1';
let saveAvailable=true, recovered=false;
function loadGame(){try{const raw=localStorage.getItem(saveKey);if(raw){const saved=JSON.parse(raw);if(validateState(saved))return saved;recovered=true;}}catch{recovered=true;}return createGame();}
let game=loadGame(), selected=game.units[1]?.uid, tab='battle', modal=null, craft=[], codexCost=0, codexQuery='', battleAnimating=false, toastTimer, battleTimer, previousFocus=null;
const app=document.getElementById('app'),modalRoot=document.getElementById('modal-root');
function save(){try{localStorage.setItem(saveKey,JSON.stringify(game));saveAvailable=true;}catch{saveAvailable=false;}}
function toast(message){if(!message)return;const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function perform(action,{quiet=false}={}){const result=act(game,action);if(result.ok){save();if(!game.units.some(u=>u.uid===selected))selected=game.units.find(u=>u.zone==='front')?.uid;render();}if(!quiet||!result.ok)toast(result.message);return result;}
function unitCard(unit,kind='front'){
 const c=getCharacter(unit.characterId);return `<button class="unit-card ${selected===unit.uid?'selected':''}" style="--char:${c.color}" data-action="select" data-uid="${unit.uid}" draggable="true" aria-label="选择${c.name}，${unit.star}星" aria-pressed="${selected===unit.uid}"><img src="${c.image}" alt="" draggable="false"><div class="unit-meta"><span class="element-badge">◇ ${c.element}</span><span class="stars">${'★'.repeat(unit.star)}</span></div><div class="unit-info"><h3>${c.name}</h3><div class="unit-tags">${c.traits.map(t=>`<span>${traitName(t)}</span>`).join('')}</div><div class="equipped-icons">${Array.from({length:3},(_,i)=>unit.items[i]?`<span class="equipped-icon" title="${getEquipment(unit.items[i]).name}">${getEquipment(unit.items[i]).icon}</span>`:'<span class="equipped-icon empty">＋</span>').join('')}</div></div></button>`;
}
function emptySlot(zone,index){return `<div class="empty-slot" data-zone="${zone}">${zone==='bench'?`<span>${index+1}</span>`:`${icon(zone==='back'?'plus':'users')}<span>${zone==='front'?'部署角色':'后台协同'}</span><span class="slot-number">SLOT 0${index+1}</span>`}</div>`;}
function row(zone,max){const units=game.units.filter(u=>u.zone===zone);return units.map(u=>unitCard(u,zone)).join('')+Array.from({length:Math.max(0,max-units.length)},(_,i)=>emptySlot(zone,units.length+i)).join('');}
function header(){return `<header class="topbar"><div class="brand">${icon('star','brand-mark')}<div><div class="brand-name">货币战争</div><span class="brand-sub">CURRENCY WARS</span></div><span class="edition">经典回响</span></div><nav class="navigation" aria-label="主要导航">${[['battle','swords','作战筹备'],['workshop','hammer','装备工坊'],['codex','book','角色图鉴']].map(([id,i,name])=>`<button class="nav-item ${tab===id?'active':''}" data-action="tab" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(i)}${name}</button>`).join('')}</nav><div class="top-actions"><span class="save-indicator">${saveAvailable?'进度已保存':'仅本次会话'}</span><button class="icon-button" data-action="help" title="玩法指南 (?)" aria-label="玩法指南">${icon('help')}</button><button class="icon-button reset-icon" data-action="restart" title="重新开始" aria-label="重新开始">${icon('reset')}</button></div></header>`;}
function overview(){const plane=Math.ceil(game.round/4);return `<section class="overview"><div><div class="eyebrow">CLASSIC ECHOES / SINGLE PLAYER</div><div class="page-title"><h1>${tab==='battle'?'重返，最初的博弈。':tab==='workshop'?'工欲善其事。':'熟悉的面孔，再次并肩。'}</h1><span class="stage-chip">${game.phase==='ended'?'远征结束':'准备阶段'}</span></div><p class="overview-desc">${tab==='battle'?`第 ${plane} 位面 · ${['启程之地','博弈之间','终局回响'][plane-1]}<span class="muted">&nbsp;&nbsp;/&nbsp;&nbsp;</span> 招募、部署，让每一次选择都有回响。`:tab==='workshop'?'挑选两件简易装备，为你的核心角色打造更强战力。':'每一张卡，都是下一场胜利的可能。'}</p></div><div class="resources"><div class="resource life">${icon('heart')}<div><div class="resource-value">${game.hp}<em> / 100</em></div><div class="resource-label">小队生命</div></div></div><span class="resource-separator"></span><div class="resource">${icon('coin')}<div><div class="resource-value">${game.gold}<em class="mint"> +${Math.min(game.strategies.includes('compound')?8:5,Math.floor(game.gold/10))}</em></div><div class="resource-label">持有金币 <span class="muted">/ 预计利息</span></div></div></div><span class="resource-separator"></span><div class="resource level">${icon('level')}<div><div class="resource-value"><em>Lv.</em> ${game.level}</div><div class="resource-label">${game.level===8?'已达最高人口':`经验 ${game.xp} / ${LEVEL_XP[game.level]}`} · 人口 ${game.level}</div></div></div></div></section>`;}
function synergies(){return `<section class="panel"><div class="panel-heading"><h2>${icon('grid')}阵容羁绊</h2><span>SYNERGIES</span></div><div class="synergy-list">${getSynergies(game).map(s=>`<button class="synergy ${s.active?'activated':''}" data-action="trait" data-id="${s.id}" title="${s.description}"><span class="trait-symbol"><span>${s.icon}</span></span><div><div class="synergy-name">${s.name}</div><div class="synergy-bars">${s.thresholds.map(n=>`<i class="${s.count>=n?'on':''}"></i>`).join('')}</div></div><span class="synergy-count">${s.count}<span class="muted">/${s.next??s.thresholds.at(-1)}</span></span></button>`).join('')||'<p class="no-items">部署角色以激活羁绊</p>'}</div><p class="side-footnote">同名角色只计一次 · 点击查看效果</p></section>`;}
function strategies(){return `<section class="panel"><div class="panel-heading"><h2>${icon('book')}投资策略</h2><span>${game.strategies.length} / 3</span></div>${game.strategies.map(id=>{const s=STRATEGIES.find(s=>s.id===id);return `<div class="strategy-mini"><span>${s.icon}</span><div><strong>${s.name}</strong><small>${s.description}</small></div></div>`;}).join('')||`<div class="strategy-mini"><span>✧</span><div><strong>故事才刚刚开始</strong><small>第 2、6、10 回合<br>选择你的投资策略</small></div></div>`}</section>`;}
function route(){return `<section class="panel route-panel"><div class="route-head"><h2>远征进度</h2><small class="number gold">${String(game.round).padStart(2,'0')} / 12</small></div><div class="route-steps">${[1,2,3,4].map((n)=>{const round=(Math.ceil(game.round/4)-1)*4+n;return `<span class="route-step ${round<game.round?'done':round===game.round?'current':''}"><span>${n===4?'♜':round<game.round?'✓':String(round).padStart(2,'0')}</span></span>`;}).join('')}</div><div class="route-captions"><span>整备 · 交锋 · 成长</span><span>位面首领</span></div></section>`;}
function board(){return `<section class="board"><div class="board-top"><div class="section-title">${icon('swords')}<h2>作战阵容</h2><span class="tiny-label">FRONTLINE</span></div><span class="team-count">${game.units.filter(u=>u.zone!=='bench').length} <span>/ ${game.level} 已部署</span></span></div><div class="front-row" data-zone="front">${row('front',4)}</div><div class="line-label">后台协同 · BACKLINE</div><div class="back-row" data-zone="back">${row('back',Math.max(4,game.units.filter(u=>u.zone==='back').length))}</div><div class="board-footer"><span>${icon('info')}点击角色调整部署，或拖动到目标区域</span><span>前台最多 4 人 · 后台协同 ${game.strategies.includes('backline')?'100':'72'}%</span></div></section><section class="bench-wrap"><div class="subsection-head"><h2>${icon('users')}备战席 <span class="number muted">${game.units.filter(u=>u.zone==='bench').length} / 8</span></h2><span class="tiny-label">3 张同星角色自动升星</span></div><div class="bench" data-zone="bench">${row('bench',8)}</div></section>`;}
function shop(){const probabilities={4:[55,32,13,0,0],5:[40,35,20,5,0],6:[27,33,28,10,2],7:[18,28,32,18,4],8:[12,20,30,28,10]};return `<section class="shop"><div class="shop-heading"><h2>${icon('shop')}角色商店 <span class="tiny-label section-sub">RECRUITMENT</span></h2><div class="shop-actions"><button class="secondary-button ${game.locked?'active':''}" data-action="lock" title="${game.locked?'解除锁定':'锁定下回合商店'}" aria-label="${game.locked?'解除商店锁定':'锁定商店'}" aria-pressed="${game.locked}">${icon(game.locked?'lock':'unlock')}</button><button class="secondary-button" data-action="exp" ${game.gold<4||game.level===8?'disabled':''} title="购买4经验 (E)">${icon('level')}购经验<span class="price">4 ${icon('coin')}</span></button><button class="secondary-button" data-action="refresh" ${game.gold<(game.strategies.includes('discount')?1:2)?'disabled':''} title="刷新商店 (R)">${icon('refresh')}刷新<span class="price">${game.strategies.includes('discount')?1:2} ${icon('coin')}</span></button></div></div><div class="shop-cards">${game.shop.map((id,i)=>{if(!id)return `<div class="shop-sold">${icon('check')}<span>已招募</span></div>`;const c=getCharacter(id),copies=game.units.filter(u=>u.characterId===id&&u.star===1).length;return `<button class="shop-card" style="--char:${c.color};--rarity:${rarity[c.cost]}" data-action="buy" data-index="${i}" ${game.gold<c.cost?'disabled':''} aria-label="招募${c.name}，${c.cost}金币"><img src="${c.image}" alt="" draggable="false"><span class="cost-badge">${icon('coin')}${c.cost}</span>${copies?`<span class="owned-badge">已拥有 ${copies}/3</span>`:''}<div class="shop-info"><h3>${c.name}</h3><small>${c.traits.map(traitName).join(' · ')}</small></div><span class="buy-hint">招募 ＋</span></button>`;}).join('')}</div><div class="shop-footer"><span>${game.locked?'商店已锁定 · 下回合保留当前角色':'每回合自动刷新 · 锁定可保留心仪角色'}</span><div class="shop-probs"><span class="muted">Lv.${game.level} 概率</span>${probabilities[game.level].map((p,i)=>`<span style="color:${rarity[i+1]}">${p}%</span>`).join('')}</div></div></section>`;}
function detail(){const unit=game.units.find(u=>u.uid===selected);if(!unit)return `<section class="panel selected-panel"><div class="panel-heading"><h2>角色详情</h2></div><p class="no-items">选择一位角色<br>查看属性与调整部署</p></section>`;const c=getCharacter(unit.characterId),stats=getUnitStats(game,unit);return `<section class="panel selected-panel" style="--char:${c.color}"><div class="detail-top"><img src="${c.image}" alt=""><div class="detail-title"><small>CHARACTER DETAILS</small><h2>${c.name}</h2><span class="stars">${'★'.repeat(unit.star)}</span></div><span class="detail-role">${c.element} · ${c.role} · ${{front:'前台',back:'后台',bench:'备战'}[unit.zone]}</span></div><div class="detail-body"><div class="detail-stats"><div class="detail-stat"><small>攻击</small><span>${stats.attack}</span></div><div class="detail-stat"><small>生命</small><span>${fmt(stats.hp)}</span></div><div class="detail-stat"><small>速度</small><span>${stats.speed}</span></div></div><div class="skill-name">${icon('star')}${c.skill}</div><p class="skill-desc">${c.description}</p><div class="detail-items">${Array.from({length:3},(_,i)=>unit.items[i]?`<button class="item-slot filled" data-action="unequip" data-uid="${unit.uid}" data-index="${i}" title="${getEquipment(unit.items[i]).name}：${getEquipment(unit.items[i]).description} 点击卸下" aria-label="卸下${getEquipment(unit.items[i]).name}">${getEquipment(unit.items[i]).icon}</button>`:'<span class="item-slot" title="从装备仓库选择装备">＋</span>').join('')}</div><div class="unit-controls">${['front','back','bench'].filter(z=>z!==unit.zone).map(z=>`<button class="secondary-button" data-action="move" data-uid="${unit.uid}" data-zone="${z}">${{front:'移至前台',back:'移至后台',bench:'移至备战'}[z]}</button>`).join('')}</div><button class="sell-button" data-action="sell" data-uid="${unit.uid}">出售角色 <span class="gold">+ ${c.cost*3**(unit.star-1)} 金币</span></button></div></section>`;}
function inventory(){return `<section class="panel"><div class="panel-heading"><h2>${icon('bag')}装备仓库</h2><button data-action="tab" data-tab="workshop" title="进入装备工坊" aria-label="进入装备工坊">${icon('expand')}</button></div><div class="inventory">${game.inventory.map((id,i)=>{const e=getEquipment(id);return `<button class="inventory-item" data-action="item" data-index="${i}" title="${e.name}：${e.description}" aria-label="装备${e.name}">${e.icon}</button>`;}).join('')}${Array.from({length:Math.max(0,4-game.inventory.length)},()=>'<span class="inventory-item empty">＋</span>').join('')}</div><p class="inventory-note">点击装备分配给角色 · 工坊内可合成</p></section>`;}
function battlePanel(){const enemy=getEnemy(game),power=getTeamPower(game);return `<section class="panel battle-panel"><div class="enemy-label"><span>下一场交锋</span><span class="number">${String(game.round).padStart(2,'0')} / 12</span></div><div class="enemy-name">${icon(enemy.boss?'crown':'shield')}${enemy.name}${enemy.boss?'<small class="gold">BOSS</small>':''}</div><div class="power-row"><span>我方战力 <b class="mint">${fmt(power)}</b></span><span>敌方 <b>${fmt(enemy.power)}</b></span></div><div class="power-track"><i style="width:${Math.min(95,power/(power+enemy.power)*100)}%"></i></div><button class="battle-button" data-action="battle" ${game.phase!=='prep'?'disabled':''}>${icon('swords')}开始战斗${icon('arrow')}</button><p class="battle-note">${power>=enemy.power?'阵容已占优势，准备出发。':'战力略有不足，试试升星或装备。'}</p></section>`;}
function battlePage(){return `<div class="workspace"><aside class="left-column">${synergies()}${strategies()}${route()}</aside><div class="center-column">${board()}${shop()}</div><aside class="right-column">${detail()}${inventory()}${battlePanel()}</aside></div>`;}
function workshop(){const a=getEquipment(game.inventory[craft[0]]),b=getEquipment(game.inventory[craft[1]]),result=a&&b?getEquipment(RECIPES[[a.id,b.id].sort().join('+')]||'hybrid'):null;return `<section class="panel page-panel"><div class="tab-page-head"><div><h2>装备工坊 <span class="tiny-label">EQUIPMENT WORKSHOP</span></h2><p>选择仓库中的两件简易装备，预览并合成进阶装备。</p></div><button class="secondary-button" data-action="tab" data-tab="battle">${icon('arrow')}返回筹备</button></div><div class="workshop-layout"><div><h3>装备仓库 <small>${game.inventory.length} 件</small></h3><div class="workshop-inventory">${game.inventory.map((id,i)=>{const e=getEquipment(id);return `<button class="workshop-item ${craft.includes(i)?'selected':''}" data-action="craft-select" data-index="${i}" ${e.tier!==1?'disabled':''} title="${e.description}"><span>${e.icon}</span><strong>${e.name}</strong><small>${e.tier===1?'简易装备':'进阶装备'}</small></button>`;}).join('')||'<p class="no-items">仓库空空的，卸下装备或赢取补给吧。</p>'}</div><div class="recipe-list"><h3>合成图谱</h3>${Object.entries(RECIPES).map(([key,id])=>`<div class="recipe-row"><span>${key.split('+').map(x=>getEquipment(x).name).join(' ＋ ')}</span><span>${getEquipment(id).name}</span></div>`).join('')}<div class="recipe-row"><span>其他任意两件简易装备</span><span>复合式战斗模块</span></div></div></div><div><div class="crafting-station"><small class="eyebrow">SOMETHING GREATER, TOGETHER</small><div class="crafting-slots"><div class="crafting-slot">${a?a.icon:'＋'}</div><span class="muted">＋</span><div class="crafting-slot">${b?b.icon:'＋'}</div></div><div class="craft-result"><span>${result?result.icon:'◇'}</span><h3>${result?result.name:'等待合成'}</h3><p>${result?result.description:'从左侧选择两件简易装备'}</p><button class="primary-button" data-action="combine" ${!result?'disabled':''}>${icon('hammer')} 确认合成</button></div></div><p class="helper-note">合成会消耗所选的两件简易装备。已穿戴装备可在角色详情中免费卸下。进阶装备无法继续合成。</p></div></div></section>`;}
function codex(){const list=CHARACTERS.filter(c=>(!codexCost||c.cost===codexCost)&&(!codexQuery||`${c.name}${c.element}${c.traits.map(traitName).join('')}`.includes(codexQuery)));return `<section class="panel page-panel"><div class="tab-page-head"><div><h2>角色图鉴 <span class="tiny-label">CHARACTER ARCHIVE</span></h2><p>24 位同行者 · 当前为经典玩法改编数值</p></div><span class="number muted">${list.length} / 24</span></div><div class="codex-controls">${[0,1,2,3,4,5].map(n=>`<button class="filter-button ${codexCost===n?'active':''}" data-action="filter" data-cost="${n}">${n?`${n} 费角色`:'全部角色'}</button>`).join('')}<input id="codex-search" class="search-input" placeholder="搜索角色、属性、羁绊" aria-label="搜索角色" value="${esc(codexQuery)}"></div><div class="codex-grid">${list.map(c=>`<button class="unit-card" style="--char:${c.color}" data-action="character" data-id="${c.id}" aria-label="查看${c.name}"><img src="${c.image}" alt="" loading="lazy"><span class="cost-badge">${icon('coin')}${c.cost}</span><div class="unit-info"><h3>${c.name}</h3><div class="unit-tags">${c.traits.map(t=>`<span>${traitName(t)}</span>`).join('')}</div><small>${c.element} · ${c.role}</small></div></button>`).join('')||'<p class="no-items">没有匹配的角色。</p>'}</div></section>`;}
function footer(){return `<footer class="bottom-bar"><span>${icon('star')}以经典为灵感，为热爱而重逢。<br>非官方同人作品 · 玩法与数值简化 · 角色素材归 HoYoverse 所有</span><div class="bottom-links"><button data-action="history">战斗记录</button><button data-action="help">玩法指南</button><a href="https://github.com/wudifeixue/CurrencyWarsClassic" target="_blank" rel="noopener">GitHub ↗</a></div></footer>`;}
function render(){app.innerHTML=header()+`<main class="shell">${overview()}${tab==='battle'?battlePage():tab==='workshop'?workshop():codex()}${footer()}</main>`;renderModal();}
function openModal(value){previousFocus=document.activeElement;modal=value;renderModal();}
function closeModal(){modal=null;renderModal();previousFocus?.focus?.();}
function modalFrame(body,{wide=false,close=true,center=false}={}){return `<div class="overlay" data-action="backdrop"><section class="modal ${center?'modal-centered':''}" role="dialog" aria-modal="true" aria-labelledby="modal-heading" tabindex="-1" ${wide?'style="width:min(900px,100%)"':''}>${close?`<button class="icon-button modal-close" data-action="close" aria-label="关闭">${icon('close')}</button>`:''}${body}</section></div>`;}
function renderModal(){let html='';
 if(battleAnimating){const e=getEnemy(game);html=modalFrame(`<div class="result-emblem">${icon('swords')}</div><div class="modal-kicker">BATTLE IN PROGRESS</div><h1 id="modal-heading">正在与${e.name}交锋</h1><p class="modal-intro">前台出击，后台协同。你的每一次选择正在汇聚成力量。</p><div class="battle-progress"><i></i></div>`,{close:false,center:true});}
 else if(game.phase==='choice'){const strategy=game.choiceKind==='strategy';html=modalFrame(`<div class="modal-kicker">${strategy?'MAKE YOUR NEXT INVESTMENT':'A GIFT FOR YOUR JOURNEY'}</div><h1 id="modal-heading">${strategy?'机遇，从选择开始。':'下一段旅途的补给。'}</h1><p class="modal-intro">第 ${game.round} 回合 · ${strategy?'从三项投资策略中选择一项，效果持续到远征结束。':'选择一件简易装备，装备给角色或前往工坊合成。'}</p><div class="choice-cards">${game.choices.map((choice,i)=>{const item=strategy?STRATEGIES.find(s=>s.id===choice.id):getEquipment(choice.id);return `<button class="choice-card" data-action="choose" data-index="${i}"><div class="choice-rarity">${strategy?item.rarity+' · 投资策略':'补给 · 简易装备'}</div><span class="choice-icon">${item.icon}</span><h2>${item.name}</h2><p>${item.description}</p><span class="choice-select">选择此项 ${icon('arrow')}</span></button>`;}).join('')}</div>`,{wide:true,close:false});}
 else if(game.phase==='result'){const b=game.lastBattle;html=modalFrame(`<div class="result-emblem">${icon(b.won?'crown':'shield')}</div><div class="modal-kicker">${b.won?'INVESTMENT PAID OFF':'A MOMENT TO REGROUP'}</div><h1 id="modal-heading">${b.won?'漂亮的一场胜利。':'重整阵容，再战一程。'}</h1><p class="modal-intro">第 ${game.round} 回合 · ${esc(b.enemy)} · ${b.won?'敌方防线已突破':`小队生命 −${b.damage}`}</p><div class="result-stats"><div><strong>${fmt(b.playerPower)}</strong><small>我方战力</small></div><div><strong>+${b.income}</strong><small>本回合收入</small></div><div><strong>${game.hp}</strong><small>剩余生命</small></div></div><div class="battle-logs">${b.logs.map(line=>`<div class="battle-log">${esc(line)}</div>`).join('')}</div><p class="helper-note">${b.rewards.map(esc).join(' · ')}</p><div class="modal-footer"><button class="primary-button" data-action="next">${game.round===12||game.hp===0?'查看远征结果':'继续远征'} ${icon('arrow')}</button></div>`,{close:false,center:true});}
 else if(game.phase==='ended'&&!modal){const won=game.result==='victory';html=modalFrame(`<div class="result-emblem">${icon(won?'crown':'star')}</div><div class="modal-kicker">${won?'CLASSIC NEVER FADES':'EVERY END IS A NEW BEGINNING'}</div><h1 id="modal-heading">${won?'经典，因你而延续。':'下一次，会是更好的选择。'}</h1><p class="modal-intro">${won?'你击败了末日兽，完成全部 12 关远征。':'这场远征暂告一段落。试试不同的羁绊与投资路线。'}</p><div class="result-stats"><div><strong>${game.round}</strong><small>抵达关卡</small></div><div><strong>${game.wins}</strong><small>胜利场数</small></div><div><strong>${fmt(getTeamPower(game))}</strong><small>最终战力</small></div></div><div class="modal-footer" style="justify-content:center"><button class="secondary-button" data-action="history">查看战斗记录</button><button class="primary-button" data-action="new-game">再来一局 ${icon('reset')}</button></div>`,{close:false,center:true});}
 else if(modal?.type==='help'){html=modalFrame(`<div class="modal-kicker">WELCOME BACK, TRAILBLAZER</div><h1 id="modal-heading">熟悉的博弈，轻装上阵。</h1><p class="modal-intro">一局 12 关，组建你的队伍，击败最终首领。进度会自动保存在当前浏览器。</p><div class="help-grid">${[['01 / 招募与升星','点击商店卡牌招募角色。三张同星角色自动合成更高星级，最高三星。刷新花费 2 金币，锁店可保留到下回合。'],['02 / 部署与羁绊','前台最多 4 人，前台与后台总人数不超过等级。备战角色不参战。点击角色选择位置，或拖动到对应区域；同名角色只计一次羁绊。'],['03 / 装备与合成','点击仓库装备，再选择穿戴角色。每人最多 3 件，点击已装备图标可免费卸下。工坊中两件简易装备可合成进阶装备。'],['04 / 运营与投资','每留 10 金币获得 1 利息，通常上限 5。购买经验提升人口。第 2、6、10 回合选择投资卡，其他补给回合可选择装备。'],['05 / 自动战斗','战力由角色属性、星级、装备、羁绊与投资策略计算，前台贡献 100%，后台通常 72%。我方战力达到敌方即可胜利。'],['06 / 远征与结算','第 4、8、12 关为首领。战败会扣生命；生命耗尽或最后一关失败则远征结束。稳住经济，升星与升人口同样重要。']].map(([title,text])=>`<div class="help-item"><h3>${title}</h3><p>${text}</p></div>`).join('')}</div><p class="helper-note">快捷键：R 刷新 · E 购买经验 · 空格开始战斗 · ? 查看指南<br>本作为非官方同人改编，采用独立平衡的角色费用、羁绊与战力结算，不是原游戏数值或技能的完整复刻。</p><div class="modal-footer"><button class="secondary-button" data-action="restart">重新开始</button><button class="primary-button" data-action="close">准备好了</button></div>`,{wide:true});}
 else if(modal?.type==='restart'){html=modalFrame(`<div class="modal-kicker">A NEW JOURNEY</div><h1 id="modal-heading">开启一场新的远征？</h1><p class="modal-intro">本次第 ${game.round} 回合的进度将被新游戏替换。新一局会重新生成商店与奖励。</p><div class="modal-footer"><button class="secondary-button" data-action="close">继续当前远征</button><button class="primary-button" data-action="new-game">重新开始</button></div>`);}
 else if(modal?.type==='trait'){const t=TRAITS.find(t=>t.id===modal.id),s=getSynergies(game).find(s=>s.id===t.id);html=modalFrame(`<div class="modal-kicker">SYNERGY DETAILS</div><h1 id="modal-heading">${t.icon} ${t.name}</h1><p class="modal-intro">${t.description}</p><div class="help-item" style="margin-top:20px"><h3>激活人数：${t.thresholds.join(' / ')}</h3><p>目前已部署 ${s?.count||0} 名不同角色。前台与后台都计入羁绊，备战席不计入。</p></div><p class="helper-note">拥有此羁绊：${CHARACTERS.filter(c=>c.traits.includes(t.id)).map(c=>c.name).join('、')}</p>`);}
 else if(modal?.type==='item'){const e=getEquipment(game.inventory[modal.index]);if(e)html=modalFrame(`<div class="modal-kicker">EQUIP YOUR TEAM</div><h1 id="modal-heading">${e.icon} ${e.name}</h1><p class="modal-intro">${e.description}</p><p class="helper-note">选择一位角色装备 · 每位角色最多 3 件</p><div class="equip-targets">${game.units.map(u=>{const c=getCharacter(u.characterId);return `<button class="equip-target" data-action="equip" data-uid="${u.uid}" data-index="${modal.index}" ${u.items.length>=3?'disabled':''}><img src="${c.image}" alt=""><strong>${c.name} <span class="gold">${'★'.repeat(u.star)}</span></strong><small>${{front:'前台',back:'后台',bench:'备战席'}[u.zone]} · 装备 ${u.items.length}/3</small></button>`;}).join('')}</div>`);}
 else if(modal?.type==='character'){const c=getCharacter(modal.id);html=modalFrame(`<div class="modal-kicker">CHARACTER ARCHIVE</div><h1 id="modal-heading">${c.name} <small>${c.cost} 费 · ${c.element} · ${c.role}</small></h1><div style="display:flex;align-items:center;gap:25px;margin-top:20px"><img src="${c.image}" alt="${c.name}" style="width:40%;max-height:290px;object-fit:contain"><div><h3 class="gold">${c.skill}</h3><p class="modal-intro">${c.description}</p><p class="helper-note">基础攻击 ${c.attack} · 基础生命 ${c.hp}<br>羁绊：${c.traits.map(traitName).join(' / ')}<br>技能名称用于角色风味展示，实际战斗以属性战力结算。</p></div></div>`);}
 else if(modal?.type==='history'){html=modalFrame(`<div class="modal-kicker">THE JOURNEY SO FAR</div><h1 id="modal-heading">远征战报</h1><p class="modal-intro">${game.wins} 胜 / ${game.losses} 负 · 当前第 ${game.round} 关</p><div class="battle-logs" style="margin-top:20px;max-height:50vh">${game.history.map(b=>`<div class="battle-log">第 ${String(b.round).padStart(2,'0')} 关 <span class="${b.won?'mint':'gold'}">${b.won?'胜利':'失利'}</span> · 战力 ${fmt(b.playerPower)} / ${fmt(b.enemyPower)} · 收入 +${b.income}${b.damage?` · 生命 −${b.damage}`:''}</div>`).join('')||'第一场交锋还未开始。'}</div>`);}
 const changed=modalRoot.innerHTML!==html;if(changed){modalRoot.innerHTML=html;document.body.style.overflow=html?'hidden':'';app.inert=!!html;if(html)requestAnimationFrame(()=>modalRoot.querySelector('button:not(:disabled),[tabindex="-1"]')?.focus());}
}
function startBattle(){if(battleAnimating||game.phase!=='prep')return;const r=act(game,{type:'battle'});if(!r.ok){toast(r.message);return;}save();battleAnimating=true;modal=null;renderModal();clearTimeout(battleTimer);battleTimer=setTimeout(()=>{battleAnimating=false;render();},window.matchMedia('(prefers-reduced-motion: reduce)').matches?50:1800);}
function handleAction(button){const a=button.dataset.action,i=Number(button.dataset.index),uid=button.dataset.uid;
 switch(a){
 case 'tab':tab=button.dataset.tab;craft=[];render();break;
 case 'select':selected=uid;render();break;
 case 'buy':perform({type:'buy',index:i});break;
 case 'refresh':case 'exp':case 'lock':perform({type:a});break;
 case 'move':perform({type:'move',uid,zone:button.dataset.zone});break;
 case 'sell':perform({type:'sell',uid});break;
 case 'unequip':perform({type:'unequip',uid,itemIndex:i});break;
 case 'battle':startBattle();break;
 case 'next':tab='battle';perform({type:'next'},{quiet:true});break;
 case 'choose':perform({type:'choose',index:i});break;
 case 'help':openModal({type:'help'});break;
 case 'restart':openModal({type:'restart'});break;
 case 'new-game':clearTimeout(battleTimer);game=createGame();selected=game.units[1].uid;tab='battle';modal=null;craft=[];battleAnimating=false;save();render();toast('新的远征，启程。');break;
 case 'close':closeModal();break;
 case 'backdrop':if(!['choice','result'].includes(game.phase)&&!battleAnimating)closeModal();break;
 case 'trait':openModal({type:'trait',id:button.dataset.id});break;
 case 'item':openModal({type:'item',index:i});break;
 case 'equip':{const result=perform({type:'equip',uid,itemIndex:i});if(result.ok){modal=null;selected=uid;render();}break;}
 case 'craft-select':if(craft.includes(i))craft=craft.filter(x=>x!==i);else craft=[...craft.slice(-1),i];render();break;
 case 'combine':if(craft.length===2){const result=perform({type:'combine',indexA:craft[0],indexB:craft[1]});if(result.ok){craft=[];render();}}break;
 case 'filter':codexCost=Number(button.dataset.cost);render();break;
 case 'character':openModal({type:'character',id:button.dataset.id});break;
 case 'history':openModal({type:'history'});break;
 }
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;if(button.dataset.action==='backdrop'&&event.target!==button)return;handleAction(button);});
function updateSearch(event){if(event.target.id!=='codex-search'||event.isComposing)return;const position=event.target.selectionStart;codexQuery=event.target.value;render();const input=document.getElementById('codex-search');input.focus();input.setSelectionRange(position,position);}
document.addEventListener('input',updateSearch);
document.addEventListener('compositionend',updateSearch);
document.addEventListener('keydown',event=>{if(event.key==='Tab'&&modalRoot.firstChild){const focusables=[...modalRoot.querySelectorAll('button:not(:disabled),a[href],input')];const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}return;}if(event.key==='Escape'&&modal&&!battleAnimating){closeModal();return;}if(event.target.matches('input,textarea')||event.ctrlKey||event.metaKey||event.altKey||event.repeat||modalRoot.firstChild)return;if(event.key==='?'){openModal({type:'help'});return;}if(tab!=='battle'||game.phase!=='prep')return;if(event.key.toLowerCase()==='r'){event.preventDefault();perform({type:'refresh'});}else if(event.key.toLowerCase()==='e'){event.preventDefault();perform({type:'exp'});}else if(event.code==='Space'&&!event.target.closest('button')){event.preventDefault();startBattle();}});
document.addEventListener('dragstart',event=>{const card=event.target.closest('[draggable="true"]');if(!card||game.phase!=='prep')return;event.dataTransfer.setData('text/plain',card.dataset.uid);event.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',event=>{const zone=event.target.closest('[data-zone]');if(zone&&!zone.matches('button')&&game.phase==='prep'){event.preventDefault();zone.classList.add('drag-over');event.dataTransfer.dropEffect='move';}});
document.addEventListener('dragleave',event=>{event.target.closest('[data-zone]')?.classList.remove('drag-over');});
document.addEventListener('drop',event=>{document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));const zone=event.target.closest('[data-zone]');if(zone&&!zone.matches('button')){event.preventDefault();perform({type:'move',uid:event.dataTransfer.getData('text/plain'),zone:zone.dataset.zone});}});
window.addEventListener('pagehide',save);
save();render();if(recovered)toast('旧存档无法读取，已为你开始新的远征。');
